run(protoc, ["-Iprotocol/hcp", `--plugin=protoc-gen-es=${protocGenEs}`, `--es_out=${tsOut}`, "--es_opt=target=ts", proto]);
await normalizeGenerated(javaOut);
await normalizeGenerated(tsOut);

if ((await readdir(javaOut)).length === 0 || (await readdir(tsOut)).length === 0) {
  throw new Error("HCP generation produced no files");
}

async function normalizeGenerated(directory) {
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const child = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      await normalizeGenerated(child);
    } else if (entry.isFile()) {
      const source = await readFile(child, "utf8");
      const normalized = `${source.replace(/[ \t]+$/gm, "").trimEnd()}\n`;
      await writeFile(child, normalized);
    }
  }
}
